def solve_flips(n):
    N = 2 * n + 1
    P_sequence = []
    for i in range(1, N + 1):
        # P_i = i * (i+1) / 2 mod N
        p_i = (i * (i + 1) // 2) % N
        P_sequence.append(p_i)

    counts = {}
    for p in P_sequence:
        counts[p] = counts.get(p, 0) + 1

    heads_down_count = 0
    for p, count in counts.items():
        if count % 2 != 0:
            heads_down_count += 1

    return heads_down_count

# Test cases
print(f"n=1 (N=3): Heads Down = {solve_flips(1)}")
